input.script:
export default async (ctx, client) => {
  return await client.notifications.send({
    title: "Which meal do you like?",
    body: "Claude Code wants to know your meal preference. Pick one:",
    input_schema: {
      type: "object",
      properties: {
        meal: {
          type: "string",
          title: "Meal",
          description: "The meal you like",
          enum: ["Pizza", "Burger", "Sushi", "Kebab", "Pasta"],
        },
      },
      required: ["meal"],
    },
  });
};
